example.configuration:

{
  "$connector_name": "example-api-key-auth-connector",
  "$connector_label": "Example API Key Authentication",
  "$connector_description": "Example REST API connector using API Key authentication",
  "$hostname": "https://api.example.com",
  "$authentication": {
    "type": "api_key",
    "headers": [
      {
        "name": "api_key",
        "label": "API Key",
        "description": "Your API key",
        "masked": true,
        "header": "Authorization",
        "value": "ApiKey $api_key"
      }
    ]
  },
  "$tables": {
    "USERS": {
      "$path": ["/v1/users"],
      "id": "INTEGER,$key",
      "username": "VARCHAR",
      "email": "VARCHAR",
      "created_at": "TIMESTAMP",
      "is_active": "BOOLEAN",
      "profile[]": {"first_name": "VARCHAR", "last_name": "VARCHAR", "avatar_url": "VARCHAR"}
    }
  }
}


{
  "$connector_name": "nbp-api-connector",
  "$connector_label": "NBP API",
  "$connector_description": "Connector for Polish National Bank (NBP) public REST API providing exchange rates and gold prices",
  "$hostname": "https://api.nbp.pl",
  "$authentication": { "type": "none" },
  "$tables": {
    "GOLD_PRICES": {
      "$path": ["/api/cenyzlota/last/50"],
      "ROWID": "VARCHAR,$key",
      "data": "DATE",
      "cena": "DECIMAL"
    }
  }
}


{
  "$connector_name": "example-oauth2-auth-connector",
  "$connector_label": "Example OAuth2 Authentication",
  "$connector_description": "Example REST API connector using OAuth2 Bearer Token authentication",
  "$hostname": "https://api.example.com",
  "$authentication": {
    "type": "oauth2",
    "headers": [
      {
        "name": "bearer_token",
        "label": "Bearer Token",
        "description": "OAuth 2.0 access token",
        "masked": true,
        "header": "Authorization",
        "value": "Bearer $bearer_token"
      }
    ]
  },
  "$tables": {
    "CUSTOMERS": {
      "$path": ["/v2/customers"],
      "customer_id": "INTEGER,$key",
      "first_name": "VARCHAR",
      "last_name": "VARCHAR",
      "email": "VARCHAR",
      "registration_date": "DATE",
      "total_purchases": "DECIMAL"
    }
  }
}


{
  "$connector_name": "example-basic-auth-connector",
  "$connector_label": "Example Basic Authentication",
  "$connector_description": "Example REST API connector using Basic (username/password) authentication",
  "$hostname": "https://api.example.com",
  "$authentication": {
    "type": "basic",
    "headers": [
      {
        "name": "username",
        "label": "Username",
        "description": "Your username",
        "masked": false,
        "header": "Authorization",
        "value": "Basic base64($username:$password)"
      },
      {
        "name": "password",
        "label": "Password",
        "description": "Your password",
        "masked": true,
        "header": null,
        "value": null
      }
    ]
  },
  "$tables": {
    "EMPLOYEES": {
      "$path": ["/api/employees"],
      "employee_id": "INTEGER,$key",
      "first_name": "VARCHAR",
      "last_name": "VARCHAR",
      "email": "VARCHAR",
      "department": "VARCHAR",
      "hire_date": "DATE",
      "salary": "DECIMAL",
      "is_manager": "BOOLEAN"
    }
  }
}


{
  "$connector_name": "example-custom-auth-connector",
  "$connector_label": "Example Custom Authentication",
  "$connector_description": "Example REST API connector using custom authentication headers",
  "$hostname": "https://api.example.com",
  "$authentication": {
    "type": "custom",
    "headers": [
      {
        "name": "x_api_key",
        "label": "API Key",
        "description": "Your primary API key",
        "masked": true,
        "header": "X-API-Key",
        "value": "$x_api_key"
      },
      {
        "name": "x_tenant_id",
        "label": "Tenant ID",
        "description": "Your tenant identifier",
        "masked": false,
        "header": "X-Tenant-ID",
        "value": "$x_tenant_id"
      }
    ]
  },
  "$tables": {
    "ORDERS": {
      "$path": ["/api/orders"],
      "order_id": "INTEGER,$key",
      "customer_id": "INTEGER",
      "status": "VARCHAR",
      "created_at": "TIMESTAMP",
      "total_amount": "DECIMAL"
    }
  }
}

example.accept_header_examples:

// Standard JSON API (default — can be omitted, but being explicit is recommended)
"$accept_header": "application/json"

// Dwolla HAL+JSON API
"$accept_header": "application/vnd.dwolla.v1.hal+json"

// GitHub REST API v3
"$accept_header": "application/vnd.github.v3+json"

// Generic HAL
"$accept_header": "application/hal+json"

