      "description": "Your tenant identifier",
      "masked": false,
      "header": "X-Tenant-ID",
      "value": "$x_tenant_id"
    }
  ]
}

example.configuration:

{
  "$connector_name": "product-catalog-api",
  "$connector_label": "Product Catalog",
  "$connector_description": "Product catalog with complex nested structures",
  "$hostname": "https://api.example.com",
  "$authentication": { "type": "none" },
  "$tables": {
    "products": {
      "$path": ["/api/products"],
      "id": "VARCHAR,$key",
      "name": "VARCHAR",
      "price": "DECIMAL",
      "specifications[]": {
        "dimensions[]": {
          "width": "DECIMAL",
          "height": "DECIMAL",
          "depth": "DECIMAL",
          "unit": "VARCHAR"
        },
        "weight[]": {
          "value": "DECIMAL",
          "unit": "VARCHAR"
        },
        "materials": "VARCHAR",
      },
      "reviews": "VARCHAR",
      "variants": "VARCHAR"
    }
  }
}


{
  "$connector_name": "events-api-connector",
  "$connector_label": "Events API",
  "$connector_description": "Connector for Events API with cursor-based pagination",
  "$hostname": "https://api.example.com",
  "$authentication": "api_key",
  "$tables": {
    "EVENTS": {
      "$path": ["/api/events"],
      "$data_path": "data",
      "$pagination": {
        "type": "cursor",
        "cursor_param": "cursor",
        "next_cursor_path": "pagination.next_cursor",
        "page_size": 100
      },
      "id": "INTEGER,$key",
      "name": "VARCHAR",
      "timestamp": "TIMESTAMP"
    }
  }
}

decision.reason:
Uses dot notation to navigate to cursor in response.
Response structure: {"data": [...], "pagination": {"next_cursor": "..."}}
Path "pagination.next_cursor" extracts the cursor value.

example.configuration:

{
  "$connector_name": "products-api-connector",
  "$connector_label": "Products API",
  "$connector_description": "Connector for Products API with offset-based pagination",
  "$hostname": "https://api.example.com",
  "$authentication": { "type": "none" },
  "$tables": {
    "PRODUCTS": {
      "$path": ["/api/products"],
      "$pagination": {
        "type": "offset",
        "offset_param": "offset",
        "limit_param": "limit",
        "page_size": 100,
        "initial_offset": 0
      },
      "product_id": "INTEGER,$key",
      "name": "VARCHAR",
      "price": "DECIMAL",
      "category": "VARCHAR",
      "in_stock": "BOOLEAN"
    }
  }
}
